import{_ as t,Y as a,o as s,c as n,aq as r,H as i}from"./chunks/framework.CZHj4g6B.js";import"./chunks/theme.BZcG_oVy.js";const f=JSON.parse('{"title":"Basic Knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/knowledge.md","filePath":"en/guide/knowledge.md"}'),p={name:"en/guide/knowledge.md"};function l(d,e,h,c,u,g){const o=a("NolebaseGitChangelog");return s(),n("div",null,[e[0]||(e[0]=r(`<h1 id="basic-knowledge" tabindex="-1">Basic Knowledge <a class="header-anchor" href="#basic-knowledge" aria-label="Permalink to &quot;Basic Knowledge&quot;">​</a></h1><blockquote><p>Here is a collection of Xposed-related introductions and the key points of knowledge that need to be grasped before start.</p><p>Anyone who already knows can skip it.</p></blockquote><p>The basic knowledge content <u><strong>not necessarily completely accurate</strong></u>, please read it according to your own opinion.</p><p>If you find <strong>any errors in this page, please correct it and help us improve</strong>.</p><h2 id="related-introduction" tabindex="-1">Related Introduction <a class="header-anchor" href="#related-introduction" aria-label="Permalink to &quot;Related Introduction&quot;">​</a></h2><blockquote><p>Here&#39;s an introduction to Xposed and how Hooks work.</p></blockquote><h3 id="what-is-xposed" tabindex="-1">What is Xposed <a class="header-anchor" href="#what-is-xposed" aria-label="Permalink to &quot;What is Xposed&quot;">​</a></h3><blockquote><p>Xposed Framework is a set of open source framework services that run in Android high-privilege mode. It can affect program operation (modify the system) without modifying the APK file. Based on it, many Powerful modules that operate simultaneously without conflicting functions.</p></blockquote><p>The above content is copied from Baidu Encyclopedia.</p><h3 id="what-can-xposed-do" tabindex="-1">What can Xposed do <a class="header-anchor" href="#what-can-xposed-do" aria-label="Permalink to &quot;What can Xposed do&quot;">​</a></h3><blockquote><p>The structure below describes the basic workings and principles of Xposed.</p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Xposed Framework</span></span>
<span class="line"><span>└── App&#39;s Environment</span></span>
<span class="line"><span>    └── Hooker (Hooked)</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    App&#39;s Environment</span></span>
<span class="line"><span>    └── Hooker (Hooked)</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    ...</span></span></code></pre></div><p>We can achieve the ultimate goal of controlling its behavior by injecting the <strong>Host (App)</strong> when the <strong>Host (App)</strong> is running.</p><p>This mode of operation of Xposed is called <strong>parasitism</strong>. The Xposed Module follows the lifecycle of the host and completes its own life course within the lifecycle of the <strong>Host</strong>.</p><p>We can call the <strong>Host</strong>&#39;s methods, fields, and constructors through reflection, and use the Hook operation provided by <code>XposedBridge</code> to dynamically insert our own code before and after the method to be executed by the <strong>Host (App)</strong>, or completely replace the target, or even intercept.</p><h3 id="development-process" tabindex="-1">Development Process <a class="header-anchor" href="#development-process" aria-label="Permalink to &quot;Development Process&quot;">​</a></h3><p>Today&#39;s Xposed Manager has been completely replaced by its derivative works, and the era of <strong>SuperSU</strong> has ended, and now, with <strong>Magisk</strong>, everything behind is possible again.</p><blockquote><p>Its development history can be roughly divided into <strong>Xposed(Dalvik)</strong> → <strong>Xposed(ART)</strong> → <strong>Xposed(Magisk)</strong> → <strong>EdXposed(Riru)</strong>/<strong>LSPosed(Riru/ Zygisk)</strong></p></blockquote><h3 id="derivatives" tabindex="-1">Derivatives <a class="header-anchor" href="#derivatives" aria-label="Permalink to &quot;Derivatives&quot;">​</a></h3><blockquote><p>The structure below describes how and how the Xposed-like Hook Framework works.</p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App&#39;s Environment</span></span>
<span class="line"><span>└── Hook Framework</span></span>
<span class="line"><span>    └── Hooker (Hooked)</span></span>
<span class="line"><span>        ...</span></span></code></pre></div><p>Through the operation principle of Xposed, many frameworks of the same type have been derived. As mobile devices in today&#39;s era are more and more difficult to obtain Root permissions or even flash, and when they are not just needed, some Root-free frameworks are also produced, such as <strong>LSPatch</strong>、<strong>TaiChi</strong>.</p><p>These Hook Frameworks at the ART level can also complete the Hook process with the same principle as Xposed without using the Xposed API. The operating principle of Root-free is to modify the APK and inject the Hook process into the <strong>Host</strong>, and control it through external modules.</p><p>Another product is to use the existing functions of the Android operating environment to virtualize an environment that is completely the same as the current device system, and run App in it. This is the virtual App technology <strong>VirtualApp</strong>, which was later derived as <strong>VirtualXposed</strong> .</p><p>The Root-free frameworks mentioned above are <a href="https://github.com/LSPosed/LSPatch" target="_blank" rel="noreferrer">LSPatch</a>、<a href="https://taichi.cool/" target="_blank" rel="noreferrer">TaiChi</a>、<a href="https://github.com/asLody/VirtualApp" target="_blank" rel="noreferrer">VirtualApp</a>、<a href="https://github.com/asLody/SandVXposed" target="_blank" rel="noreferrer">SandVXposed</a>.</p><h3 id="what-yukihookapi-does" tabindex="-1">What YukiHookAPI does <a class="header-anchor" href="#what-yukihookapi-does" aria-label="Permalink to &quot;What YukiHookAPI does&quot;">​</a></h3><p>Since Xposed appeared until now, apart from <code>XposedHelpers</code>, which is well known to developers, there is still no set of syntactic sugar for Kotlin and API with complete usage encapsulation.</p><p>The birth of this API framework is to hope that in the current era of Xposed, more capable Xposed Module developers can avoid detours and complete the entire development process more easily and simply.</p><p>In the future, YukiHookAPI will adapt to more third-party Hook Frameworks based on the goal of using the Xposed API, so as to improve the entire ecosystem and help more developers make Xposed Module development simpler and easier to understand.</p><h2 id="let-s-started" tabindex="-1">Let&#39;s Started <a class="header-anchor" href="#let-s-started" aria-label="Permalink to &quot;Let&#39;s Started&quot;">​</a></h2><p>Before starting, you need to have the following basics to better use YukiHookAPI.</p><ul><li><p>Grasp and understand Android development and simple system operation principles</p></li><li><p>To grasp and understand the internal structure of Android APK and simple decompilation knowledge, you can refer to <a href="https://github.com/skylot/jadx" target="_blank" rel="noreferrer">Jadx</a> and <a href="https://github.com/iBotPeaches/Apktool" target="_blank" rel="noreferrer">ApkTool</a></p></li><li><p>Grasp and proficient in using Java reflection, understand simple Smali syntax, understand Dex file structure, and use reverse analysis to locate method locations</p></li><li><p>Grasp the basic native <a href="https://api.xposed.info" target="_blank" rel="noreferrer">Xposed API</a> usage, understand the operation principle of Xposed, see <a href="https://blog.ketal.icu/en/Xposed%E6%A8%A1%E5%9D%97%E5%BC%80%E5%8F%91%E5%85%A5%E9%97%A8%E4%BF%9D%E5%A7%86%E7%BA%A7%E6%95%99%E7%A8%8B/" target="_blank" rel="noreferrer">here</a> <strong>(Friend Link)</strong></p></li><li><p>Grasp Kotlin language and learn to use <strong>Kotlin lambda</strong></p></li><li><p>Grasp and understand Kotlin and Java mixing, calling each other, and Java bytecode generated by Kotlin</p></li></ul>`,32)),i(o)])}const b=t(p,[["render",l]]);export{f as __pageData,b as default};
